// Regenerates constants/country-names.ts — Hindi and Bengali country names for
// every ISO code the location picker lists (constants/place-countries.ts,
// generated by scripts/build-places.mjs) and every code older saved profiles
// may name (COUNTRY_CODES in constants/timezones.ts).
// Run: node scripts/gen-country-names.mjs
// Uses Node's full-ICU Intl.DisplayNames at build time only; the app never calls
// Intl.DisplayNames at runtime (Hermes support is not guaranteed).
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const read = (rel) => readFileSync(fileURLToPath(new URL(rel, import.meta.url)), 'utf8');
const codes = [...new Set([
  ...[...read('../constants/place-countries.ts').matchAll(/^\s*\["([A-Z]{2})",/gm)].map((m) => m[1]),
  ...[...read('../constants/timezones.ts').matchAll(/^\s*"[^"]+":"([A-Z]{2})",$/gm)].map((m) => m[1]),
])].sort();

const hi = new Intl.DisplayNames(['hi'], { type: 'region', fallback: 'none' });
const bn = new Intl.DisplayNames(['bn'], { type: 'region', fallback: 'none' });

const rows = [];
const missing = [];
for (const code of codes) {
  const h = hi.of(code);
  const b = bn.of(code);
  if (!h || !b) { missing.push(code); continue; } // falls back to English at runtime
  rows.push(`  ${code}: { hi: ${JSON.stringify(h.normalize('NFC'))}, bn: ${JSON.stringify(b.normalize('NFC'))} },`);
}

const out = `/**
 * Hindi and Bengali country names, keyed by ISO 3166-1 alpha-2 code.
 * GENERATED by scripts/gen-country-names.mjs (Node full-ICU Intl.DisplayNames,
 * type 'region') — do not edit by hand; re-run: node scripts/gen-country-names.mjs
 * Display only: stored places always use the English names (constants/place-countries.ts).
 */
export const COUNTRY_NAMES: Record<string, { hi: string; bn: string }> = {
${rows.join('\n')}
};
`;
writeFileSync(fileURLToPath(new URL('../constants/country-names.ts', import.meta.url)), out);
console.log(`wrote ${rows.length} countries; missing: ${missing.join(',') || 'none'}`);
